nce.'), ('vagt', 'word', '13f82438-909f-5c7a-86c3-4692f429fd3e', 2, 'noun', 'en', 'duty, watch (shift)', 'Han har vagt om natten i weekenden.', 'He has night duty at the weekend.'), ('helvede', 'word', '1b30ca59-a9fb-580d-ab4c-398a6930848e', 1, 'noun', 'et', 'hell', 'Han beskrev krigen som et helvede.', 'He described the war as hell.'), ('engel', 'word', '991d5b1f-4531-502a-9e8e-3deb920e313f', 1, 'noun', 'en', 'angel', 'Barnet ligner en lille engel.', 'The child looks like a little angel.'), ('forsikringsselskab', 'word', 'f6a97aa5-0297-5aa9-bc50-77b7720b323e', 1, 'noun', 'et', 'insurance company', 'Han ringede til sit forsikringsselskab.', 'He called his insurance company.'), ('konkurs', 'word', '335e7f0a-fbce-535d-85a7-44a14ef4b467', 1, 'adjective', null, 'bankrupt', 'Firmaet gik konkurs sidste år.', 'The company went bankrupt last year.'), ('konsekvent', 'word', '00439b6a-e0b9-5f1a-ac61-2f52909eb0cb', 1, 'adjective', null, 'consistent', 'Vær konsekvent i dine beslutninger.', 'Be consistent in your decisions.'), ('nedskæring', 'word', '496908b4-e989-51f8-93b1-d58787bd7260', 1, 'noun', 'en', 'cut, cutback (budget, staff)', 'Regeringen varslede en nedskæring i budgettet.', 'The government announced a cutback in the budget.'), ('dybde', 'word', 'db6e9194-01b8-5782-a5a2-7f65dbdf3a98', 1, 'noun', 'en', 'depth', 'Søen har en dybde på ti meter.', 'The lake has a depth of ten metres.'), ('bureau', 'word', 'c0fa8998-2864-5d60-af3f-cdc60925c4fb', 1, 'noun', 'et', 'bureau, agency', 'Hun arbejder på et bureau, der laver reklamer.', 'She works at an agency that makes advertisements.'), ('nøgen', 'word', '9897fff5-198e-5823-b0c2-425d4f918282', 1, 'adjective', null, 'naked, nude', 'Barnet løb nøgen rundt i haven.', 'The child ran around naked in the garden.'), ('moderat', 'word', '29ae43e6-1db7-544b-9623-29e8a59871a3', 1, 'adjective', null, 'moderate', 'Han spiser moderat mængder sukker.', 'He eats moderate amounts of sugar.'), ('basis', 'word', '8a5794ef-d88a-5d67-82e8-4727eb0e