'He was rejected on his application.'), ('tolke', 'word', '71e7f5a6-6095-5066-b2c8-e1a8ee59edcf', 1, 'verb', null, 'to interpret (orally)', 'Hun skal tolke for gæsterne.', 'She is going to interpret for the guests.'), ('lange', 'word', 'e43fd598-029d-5dcf-8f4b-e9f2fdc44006', 1, 'verb', null, 'to pass, to hand', 'Kan du lange saltet til mig?', 'Can you pass me the salt?'), ('minus', 'word', '0fbbd26f-48bd-599f-8c39-dd83a98f1a15', 1, 'noun', 'et', 'deficit, minus', 'Firmaet har et minus på budgettet.', 'The company has a deficit in the budget.'), ('tænketank', 'word', '3facbe05-7aef-550d-a411-724c9084f9fb', 1, 'noun', 'en', 'think tank', 'Rapporten kommer fra en uafhængig tænketank.', 'The report comes from an independent think tank.'), ('ankomst', 'word', 'fa12e2ee-bfb2-5b4b-945d-8933b4a04335', 1, 'noun', 'en', 'arrival', 'Vi ventede på hendes ankomst i lufthavnen.', 'We were waiting for her arrival at the airport.'), ('begribe', 'word', 'ed4ae7bb-2c4b-565d-9264-1f1d37db9177', 1, 'verb', null, 'to grasp, to comprehend', 'Jeg kan slet ikke begribe, hvad der skete.', 'I simply cannot grasp what happened.'), ('sinde', 'word', 'c1d00ba5-84c0-5fd6-9d81-09311a72ac32', 1, 'noun', 'en', 'mind, mood (in set phrases)', 'Hun er altid glad til sinde.', 'She is always in good spirits.'), ('dilemma', 'word', '5adc1ba1-8359-55f7-a467-2386d9b7537d', 1, 'noun', 'et', 'dilemma', 'Han stod over for et svært dilemma.', 'He faced a difficult dilemma.'), ('arbejdsliv', 'word', '3cab0221-f09f-5423-bc19-309634bf57fa', 1, 'noun', 'et', 'working life', 'Hun har haft et langt arbejdsliv.', 'She has had a long working life.'), ('fortryde', 'word', '8c00c3be-996b-5434-ad6f-1e7cd0a64a3f', 1, 'verb', null, 'to regret', 'Han fortryder, at han ikke sagde det.', 'He regrets not saying it.'), ('strejke', 'word', 'f3d0d073-0b16-5405-bdb8-0fafdf3635a7', 1, 'noun', 'en', 'strike', 'Arbejderne varslede en strejke.', 'The workers announced a strike.'), ('belønne', 'word', '4e7b331c-2b29-5d45-b24e-26e055143487', 1, 'verb', null, 'to reward', 'Chefen belønnede teamet med en bonus.', 'The boss rewarded the team with a bonus.'), ('vældig', 'word', '28bb63f4-656a-51cc-b831-6d37ef7f281b', 1, 'adjective', null, 'huge, tremendous', 'Det var en vældig forskel.', 'It was a huge difference.'), ('besætning', 'word', '0e65cf44-4bdb-5734-a4f8-eb9edf084016', 1, 'noun', 'en', 'crew', 'Skibets besætning bestod af tyve mand.', 'The ship''s crew consisted of twenty men.'), ('klient', 'word', '5585028b-fc76-5a0e-87ae-5622c66a8661', 1, 'noun', 'en', 'client', 'Advokaten mødtes med sin klient.', 'The lawyer met with his client.'), ('importere', 'word', '5bb5d04e-8556-58f1-9872-de7e0a319e2b', 1, 'verb', null, 'to import', 'Danmark importerer meget frugt.', 'Denmark imports a lot of fruit.'), ('vinge', 'word', '699f6198-969b-5600-91d9-9da716571fb6', 1, 'noun', 'en', 'wing', 'Fuglen havde en skadet vinge.', 'The bird had an injured wing.'), ('definition', 'word', 'ee654503-2854-5d48-b2b1-2e80793e8a3f', 1, 'noun', 'en', 'definition', 'Ordbogen giver en klar definition.', 'The dictionary gives a clear definition.'), ('tæppe', 'word', 'ca6eb8ea-4778-581d-85b3-dc1b50df6bcc', 1, 'noun', 'et', 'blanket', 'Hun lagde et tæppe over benene.', 'She put a blanket over her legs.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
